exercise.solution:
const PRICE_PER_KILO: f64 = 2.5;
const BAG_FEE: f64 = 0.5;
const COUPON: f64 = 2.0;

fn fruit_cost(kilos: f64) -> f64 {
    let mut total = kilos * PRICE_PER_KILO;
    total += BAG_FEE;
    total
}

fn after_coupon(cost: f64) -> f64 {
    let cost = cost - COUPON;
    let cost = cost / 2.0;
    cost
}

fn main() {
    let weight = "3.5";
    let weight: f64 = weight.parse().unwrap();
    println!("{weight} kg costs {}", fruit_cost(weight));
    println!("0 kg costs {}", fruit_cost(0.0));

    let cost = fruit_cost(4.0);
    println!("Cost {cost}, after coupon {}", after_coupon(cost));
    println!("Cost 3, after coupon {}", after_coupon(3.0));

    let costs = [fruit_cost(1.5), fruit_cost(2.0)];
    print!("Costs: ");
    println!("{:?}", costs);
}
